import './local-doc174.js?v=174';
import{references171,deviceFunctions196}from'./electrical171.js?v=196';
import{drawing173,svg173,mountInstallation173}from'./installation173.js?v=196';
export const CAD_LAYERS168={MARCO:7,CA:7,CD_POS:7,RETORNO:7,PE:7,CONTROL:7,SIMBOLOS:7,TEXTOS:7};
export const drawing168=drawing173,svg168=svg173;
export function dxf168(state){const p=[],add=(...v)=>p.push(...v.map(String)),ascii=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/−|–|→|·|°|²|³/g,c=>({'−':'-','–':'-','→':'->','·':' ','°':'deg','²':'2','³':'3'}[c])).replace(/[^\x20-\x7e]/g,' ');
 add(0,'SECTION',2,'HEADER',9,'$ACADVER',1,'AC1009',9,'$MEASUREMENT',70,1,9,'$EXTMIN',10,0,20,0,30,0,9,'$EXTMAX',10,594,20,420,30,0,0,'ENDSEC',0,'SECTION',2,'TABLES',0,'TABLE',2,'LAYER',70,Object.keys(CAD_LAYERS168).length);
 for(const [name,color]of Object.entries(CAD_LAYERS168))add(0,'LAYER',2,name,70,0,62,color,6,'CONTINUOUS');add(0,'ENDTAB',0,'ENDSEC',0,'SECTION',2,'ENTITIES');
 for(const o of drawing168(state)){if(o.t==='L')add(0,'LINE',8,o.l,10,o.x,20,420-o.y,30,0,11,o.u,21,420-o.v,31,0);if(o.t==='C')add(0,'CIRCLE',8,o.l,10,o.x,20,420-o.y,30,0,40,o.r);if(o.t==='T')add(0,'TEXT',8,o.l,10,o.x,20,420-o.y,30,0,40,o.h,1,ascii(o.s),50,0);}
 add(0,'ENDSEC',0,'EOF');return p.join('\r\n')+'\r\n';
}
export function installCad168(view){
 if(view.cad174)return view.cad174;const d=view.dialog,button=document.createElement('button');button.textContent='Unifilar CAD';button.dataset.srCad168='';d.querySelector('.sr128-mode-tabs').insertBefore(button,d.querySelector('[data-sr-panel161]'));
 const overlay=document.createElement('section');overlay.className='cad168';overlay.hidden=true;overlay.setAttribute('aria-label','Plano unifilar CAD');overlay.innerHTML=`<header><div><small>SR-UN-001 · CONVENCIÓN AMERICANA</small><h3>Diagrama unifilar</h3></div><button data-cad-back>Volver a 3D ×</button></header><div class="cad168-tools"><button data-cad-zoom="1.25" aria-label="Acercar plano">＋</button><button data-cad-zoom="0.8" aria-label="Alejar plano">−</button><button data-cad-fit>Encuadrar</button><button data-cad-dxf>Descargar DXF · AutoCAD</button><button data-cad-svg>Descargar SVG</button><button data-cad-info aria-expanded="false">Simbología y referencias</button></div><div class="cad168-body"><div class="cad168-paper" tabindex="0" aria-label="Plano: rueda para zoom, arrastra para desplazar">${svg168()}</div><aside class="cad168-info" hidden><h4>Simbología / instalación / unidades</h4><p>IEEE/ANSI 315-1975 es la convención estadounidense utilizada; estado Inactive-Reserved. Funciones de dispositivo: IEEE C37.2-2022. Las cajas rotuladas REC-1, TD-AUX y TD-CTRL son bloques funcionales; no son resistencias IEC ni un circuito interno documentado.</p><dl>${deviceFunctions196.map(d=>`<dt><b>${d.tag}</b></dt><dd>${d.name}</dd>`).join('')}<dt><b>50 / 51</b></dt><dd>Sobrecorriente instantánea / de tiempo.</dd></dl><p>NMX-J-136-ANCE-2019 es la referencia mexicana de símbolos. Cotejo con textos autorizados pendiente; no se declara conformidad.</p><p>NOM-001-SEDE-2012: 1.2.2(c) excluye generación, transformación y distribución utilizadas exclusivamente por el transporte público eléctrico. Evaluar por separado servicios fijos. NOM-008-SE-2021 vigente regula unidades y escritura, no simbología de circuitos.</p><p>Topología funcional. 23 kV y 750 V son referencias del simulador, no placas verificadas. Fuente auxiliar y conexionado real por confirmar. Cxx y PE01 abren la cédula vinculada. Entradas iniciales supuestas y editables; cédulas calculadas como estimación educativa.</p><ul>${references171.map(([name,body,url])=>`<li><a target="_blank" rel="noopener" href="${url}">${name}</a>: ${body.replace('Sin selección numérica.','Estimación editable en cédulas.').replace('Faltan longitud, impedancia, carga y factor de potencia.','Entradas supuestas, por verificar con datos de instalación.')}</li>`).join('')}</ul><p>DXF R12 editable: capas negras; hoja A2 en mm. Abrir con ZOOM Extents. No es un DWG ni un plano de construcción.</p></aside></div><footer><span data-cad-status>Selecciona un símbolo para ubicar su equipo en el modelo.</span><button data-cad-model disabled>Ver equipo en 3D →</button></footer>`;d.append(overlay);
 const installation=mountInstallation173(overlay,id=>{selected=id;close();d.querySelector('[data-sr-explore-mode]').click();view.home();view.select(id,true);},state=>{const paper=overlay.querySelector('.cad168-paper'),old=paper.querySelector('svg'),box=old?.getAttribute('viewBox');paper.innerHTML=svg173(state);if(box)paper.querySelector('svg').setAttribute('viewBox',box);});
 const paper=overlay.querySelector('.cad168-paper');let box=[0,0,594,420],down=null,selected=null,wasRunning=false;
 const apply=()=>paper.querySelector('svg').setAttribute('viewBox',box.join(' '));function zoom(f,x=.5,y=.5){const w=Math.min(1188,Math.max(100,box[2]/f)),h=w*420/594;box=[box[0]+(box[2]-w)*x,box[1]+(box[3]-h)*y,w,h];apply();}
 function close(){overlay.hidden=true;d.dataset.cad168='false';view.controls.enabled=true;if(wasRunning)view.start();view.resize();button.focus();}
 button.addEventListener('click',()=>{wasRunning=!!view.frame;view.service128?.play135?.bag156?.close();view.stop();view.controls.enabled=false;overlay.hidden=false;d.dataset.cad168='true';box=[0,0,594,420];apply();overlay.querySelector('[data-cad-back]').focus();});overlay.querySelector('[data-cad-back]').onclick=close;
 overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-cad-part]')){e.preventDefault();select(e.target.closest('[data-cad-part]').dataset.cadPart);}});
 function select(id){selected=id;for(const g of paper.querySelectorAll('[data-cad-part]'))g.setAttribute('aria-pressed',String(g.dataset.cadPart===id));overlay.querySelector('[data-cad-status]').textContent=view.parts.get(id).userData.title;overlay.querySelector('[data-cad-model]').disabled=false;}
 overlay.querySelector('[data-cad-model]').onclick=()=>{close();d.querySelector('[data-sr-explore-mode]').click();view.home();view.select(selected,true);};
 for(const b of overlay.querySelectorAll('[data-cad-zoom]'))b.onclick=()=>zoom(Number(b.dataset.cadZoom));overlay.querySelector('[data-cad-fit]').onclick=()=>{box=[0,0,594,420];apply();};
 paper.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12);},{passive:false});
 paper.addEventListener('pointerdown',e=>{if(e.button!==0)return;down={x:e.clientX,y:e.clientY,box:[...box],target:e.target};paper.setPointerCapture(e.pointerId);});paper.addEventListener('pointermove',e=>{if(!down)return;const r=paper.querySelector('svg').getBoundingClientRect(),scale=Math.min(r.width/down.box[2],r.height/down.box[3]);box=[down.box[0]-(e.clientX-down.x)/scale,down.box[1]-(e.clientY-down.y)/scale,...down.box.slice(2)];apply();});paper.addEventListener('pointerup',e=>{if(!down)return;const start=down;down=null;if(paper.hasPointerCapture(e.pointerId))paper.releasePointerCapture(e.pointerId);if(Math.hypot(e.clientX-start.x,e.clientY-start.y)<5){const g=start.target.closest('[data-cad-part]');if(g)select(g.dataset.cadPart);}});paper.addEventListener('pointercancel',()=>down=null);
 overlay.querySelector('[data-cad-info]').onclick=e=>{const aside=overlay.querySelector('.cad168-info');aside.hidden=!aside.hidden;e.currentTarget.setAttribute('aria-expanded',String(!aside.hidden));};
 function download(data,type,name){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 overlay.querySelector('[data-cad-dxf]').onclick=()=>download(dxf168(installation.state),'application/dxf','MetroLab_SR-UN-001_R173.dxf');overlay.querySelector('[data-cad-svg]').onclick=()=>download(svg168(installation.state),'image/svg+xml','MetroLab_SR-UN-001_R173.svg');
 d.addEventListener('close',()=>{overlay.hidden=true;d.dataset.cad168='false';view.controls.enabled=true;down=null;});view.cad174={close,overlay,button,installation};return view.cad174;
}
